const e=[{id:"cloud",label:"Molecular cloud",kicker:"The beginning",title:"A cold place gathers itself",description:"Stars begin in cold, dense regions of molecular clouds. Gravity slowly pulls a pocket of gas and dust together while turbulence and magnetic fields shape the newborn structure.",facts:["Mostly molecular hydrogen","Temperatures near 10–20 K","Collapse can take hundreds of thousands of years"],color:"#789bb5"},{id:"protostar",label:"Protostar",kicker:"Collapse",title:"Gravity turns mass into heat",description:"As material falls inward, the forming protostar warms and spins up. A disk feeds the center, while jets can carry angular momentum away. Hydrogen fusion has not started yet.",facts:["Powered by gravitational contraction","Often surrounded by a disk","Jets can emerge from the poles"],color:"#c29c72"},{id:"main-sequence",label:"Main sequence",kicker:"The long middle",title:"A star finds its balance",description:"When the core becomes hot and dense enough for hydrogen fusion, inward gravity balances outward pressure. Most stars spend the majority of their lives here.",facts:["Hydrogen fuses into helium","The Sun is here now","Mass sets brightness and lifetime"],color:"#d7edf4"},{id:"giant",label:"Giant or supergiant",kicker:"Expansion",title:"The core changes the story",description:"When core hydrogen is exhausted, the core contracts and the outer layers expand. Sun-like stars become red giants; stars born much more massive become red or blue supergiants and can fuse heavier elements.",facts:["Sun-like path: red giant","Massive path: supergiant","Outer layers become unstable"],color:"#d58b64"},{id:"white-dwarf",label:"White dwarf",kicker:"Sun-like ending",title:"A hot ember remains",description:"A low- or intermediate-mass star sheds its outer layers, leaving a compact white dwarf. It no longer fuses elements; it slowly cools over immense timescales.",facts:["No core fusion","Earth-sized, roughly solar mass","Cooled remnant of a planetary nebula"],color:"#cce7ff",branch:"sun"},{id:"supernova",label:"Supernova",kicker:"Massive-star ending",title:"The core collapses",description:"A massive star can build an iron core that cannot release energy through fusion. The core collapses and the outer layers explode, briefly enriching space with newly forged elements.",facts:["Core-collapse explosion","Creates and scatters heavy elements","Not the fate of every star"],color:"#e7b0a1",branch:"massive"},{id:"compact-remnant",label:"Neutron star or black hole",kicker:"What is left",title:"The remnant depends on mass",description:"After a massive-star supernova, the collapsed core may become a neutron star. If the remaining core is sufficiently massive, gravity can continue the collapse into a black hole.",facts:["Neutron stars are ultra-dense","Black holes have an event horizon","The boundary depends on the remnant mass"],color:"#8e9ec7",branch:"massive"}],a=[{id:"betelgeuse",name:"Betelgeuse",constellation:"Orion",ra:88.793,dec:7.407,distance:548,x:32,y:22,magnitude:.42},{id:"bellatrix",name:"Bellatrix",constellation:"Orion",ra:81.283,dec:6.35,distance:250,x:68,y:25,magnitude:1.64},{id:"alnilam",name:"Alnilam",constellation:"Orion",ra:84.053,dec:-1.202,distance:1340,x:50,y:43,magnitude:1.69},{id:"alnitak",name:"Alnitak",constellation:"Orion",ra:85.19,dec:-1.943,distance:1260,x:35,y:47,magnitude:1.74},{id:"mintaka",name:"Mintaka",constellation:"Orion",ra:83.001,dec:-.299,distance:1200,x:65,y:45,magnitude:2.23},{id:"rigel",name:"Rigel",constellation:"Orion",ra:78.634,dec:-8.202,distance:860,x:73,y:73,magnitude:.13},{id:"saiph",name:"Saiph",constellation:"Orion",ra:86.939,dec:-9.67,distance:720,x:27,y:74,magnitude:2.07}],t=[["betelgeuse","bellatrix"],["betelgeuse","alnilam"],["bellatrix","mintaka"],["alnilam","alnitak"],["alnilam","mintaka"],["alnitak","saiph"],["mintaka","rigel"],["saiph","rigel"]],n=["NASA, “The Life Cycle of a Star” (science.nasa.gov)","ESA Gaia Archive, DR3 stellar astrometry (gea.esac.esa.int)","IAU Working Group on Star Names and constellation boundaries (iau.org)"];export{n as a,t as b,a as c,e as s};
